"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[64548],{10489:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>r,contentTitle:()=>i,default:()=>c,frontMatter:()=>a,metadata:()=>o,toc:()=>d});var h=n(31085),s=n(71184);const a={sidebar_position:14,slug:"/bible/2_Machabees/2_Machabees_14",title:"2 Machabees 14",hide_table_of_contents:!0},i="2 Machabees",o={id:"bible/2 Machabees/2 Machabees 14",title:"2 Machabees 14",description:"Chapter 14",source:"@site/docs/bible/2 Machabees/2 Machabees 14.md",sourceDirName:"bible/2 Machabees",slug:"/bible/2_Machabees/2_Machabees_14",permalink:"/bibleNotes/docs/bible/2_Machabees/2_Machabees_14",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/2 Machabees/2 Machabees 14.md",tags:[],version:"current",sidebarPosition:14,frontMatter:{sidebar_position:14,slug:"/bible/2_Machabees/2_Machabees_14",title:"2 Machabees 14",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"2 Machabees 13",permalink:"/bibleNotes/docs/bible/2_Machabees/2_Machabees_13"},next:{title:"2 Machabees 15",permalink:"/bibleNotes/docs/bible/2_Machabees/2_Machabees_15"}},r={},d=[{value:"Chapter 14",id:"chapter-14",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,s.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,h.jsxs)(h.Fragment,{children:[(0,h.jsx)(t.h1,{id:"2-machabees",children:"2 Machabees"}),"\n",(0,h.jsx)(t.h2,{id:"chapter-14",children:"Chapter 14"}),"\n",(0,h.jsx)(t.p,{children:"Demetrius challenges the kingdom.  Alcimus applies to him to be made high priest:  Nicanor is sent into Judea:  his dealings with Judas:  his threats.  The history of Razias."}),"\n",(0,h.jsx)(n,{verse:1,children:"But after the space of three years Judas, and they that were with him, understood that Demetrius, the son of Seleucus, was come up with a great power, and a navy by the haven of Tripolis, to places proper for his purpose,"}),"\n",(0,h.jsx)(n,{verse:2,children:"And had made himself master of the countries against Antiochus, and his general, Lysias."}),"\n",(0,h.jsx)(n,{verse:3,children:"Now one Alcimus, who had been chief priest, but had wilfully defiled himself in the time of mingling with the heathens, seeing that there was no safety for him, nor access to the altar,"}),"\n",(0,h.jsx)(t.admonition,{type:"note",children:(0,h.jsx)(t.p,{children:"Note 1: Now Alcimus, who had been chief priest...This Alcimus was of the stock of Aaron, but for his apostasy here mentioned was incapable of the high priesthood, but king Antiochus Eupator appointed him in place of the high priest, (see above, 1 Mac. chap. 7., ver. 9,) as Menelaus had been before him, set up by Antiochus (above chap. 4.), yet neither of them were truly high priests; for the true high priesthood was amongst the Machabees, who were also of the stock of Aaron, and had strictly held their religion, and were ordained according to the rites commanded in\r\nNote 2: the law of Moses.--Ibid. Mingling...with the heathens; that is, in their idolatrous worship."})}),"\n",(0,h.jsx)(n,{verse:4,children:"Came to king Demetrius in the year one hundred and fifty, presenting unto him a crown of gold, and a palm, and besides these, some boughs that seemed to belong to the temple. And that day indeed he held his peace."}),"\n",(0,h.jsx)(n,{verse:5,children:"But having gotten a convenient time to further his madness, being called to counsel by Demetrius, and asked what the Jews relied upon, and what were their counsels,"}),"\n",(0,h.jsx)(n,{verse:6,children:"He answered thereunto: They among the Jews that are called Assideans, of whom Judas Machabeus is captain, nourish wars, and raise seditions, and will not suffer the realm to be in peace."}),"\n",(0,h.jsx)(n,{verse:7,children:"For I also being deprived of my ancestor's glory (I mean of the high priesthood) am now come hither:"}),"\n",(0,h.jsx)(n,{verse:8,children:"Principally indeed out of fidelity to the king's interests, but in the next place also to provide for the good of my countrymen: for all our nation suffereth much from the evil proceedings of these men."}),"\n",(0,h.jsx)(n,{verse:9,children:"Wherefore, O king, seeing thou knowest all these things, take care, I beseech thee, both of the country, and of our nation, according to thy humanity which is known to all men."}),"\n",(0,h.jsx)(n,{verse:10,children:"For as long as Judas liveth it is not possible that the state should be quiet."}),"\n",(0,h.jsx)(n,{verse:11,children:"Now when this man had spoken to this effect the rest also of the king's friends, who were enemies of Judas, incensed Demetrius against him."}),"\n",(0,h.jsx)(n,{verse:12,children:"And forthwith he sent Nicanor, the commander over the elephants, governor into Judea:"}),"\n",(0,h.jsx)(n,{verse:13,children:"Giving him in charge, to take Judas himself: and disperse all them that were with him, and to make Alcimus the high priest of the great temple."}),"\n",(0,h.jsx)(n,{verse:14,children:"Then the Gentiles who had fled out of Judea, from Judas, came to Nicanor by flocks, thinking the miseries and calamities of the Jews to be the welfare of their affairs."}),"\n",(0,h.jsx)(n,{verse:15,children:"Now when the Jews heard of Nicanor's coming, and that the nations were assembled against them, they cast earth upon their heads, and made supplication to him who chose his people to keep them for ever, and who protected his portion by evident signs."}),"\n",(0,h.jsx)(n,{verse:16,children:"Then at the commandment of their captain, they forthwith removed from the place where they were, and went to the town of Dessau, to meet them."}),"\n",(0,h.jsx)(n,{verse:17,children:"Now Simon, the brother of Judas, had joined battle with Nicanor: but was frightened with the sudden coming of the adversaries."}),"\n",(0,h.jsx)(n,{verse:18,children:"Nevertheless Nicanor hearing of the valour of Judas's companions, and the greatness of courage, with which they fought for their country, was afraid to try the matter by the sword."}),"\n",(0,h.jsx)(n,{verse:19,children:"Wherefore he sent Posidonius, and Theodotius and Matthias before to present and receive the right hands."}),"\n",(0,h.jsx)(n,{verse:20,children:"And when there had been a consultation thereupon, and the captain had acquainted the multitude with it, they were all of one mind to consent to covenants."}),"\n",(0,h.jsx)(n,{verse:21,children:"So they appointed a day upon which they might come together by themselves: and seats were brought out, and set for each one."}),"\n",(0,h.jsx)(n,{verse:22,children:"But Judas ordered armed men to be ready in convenient places, lest some mischief might be suddenly practised by the enemies: so they made an agreeable conference."}),"\n",(0,h.jsx)(n,{verse:23,children:"And Nicanor abode in Jerusalem, and did no wrong, but sent away the flocks of the multitudes that had been gathered together."}),"\n",(0,h.jsx)(n,{verse:24,children:"And Judas was always dear to him from the heart, and he was well affected to the man."}),"\n",(0,h.jsx)(n,{verse:25,children:"And he desired him to marry a wife, and to have children. So he married: he lived quietly, and they lived in common."}),"\n",(0,h.jsx)(n,{verse:26,children:"But Alcimus seeing the love they had one to another, and the covenants, came to Demetrius, and told him that Nicanor had assented to the foreign interest, for that he meant to make Judas, who was a traitor to the kingdom, his successor."}),"\n",(0,h.jsx)(n,{verse:27,children:"Then the king, being in a rage, and provoked with this man's wicked accusation, wrote to Nicanor, signifying that he was greatly displeased with the covenant of friendship: and that he commanded him nevertheless to send Machabeus prisoner in all haste to Antioch."}),"\n",(0,h.jsx)(n,{verse:28,children:"When this was known, Nicanor was in a consternation, and took it grievously that he should make void the articles that were agreed upon, having received no injury from the man."}),"\n",(0,h.jsx)(n,{verse:29,children:"But because he could not oppose the king, he watched an opportunity to comply with the orders"}),"\n",(0,h.jsx)(n,{verse:30,children:"But when Machabeus perceived that Nicanor was more stern to him, and that when they met together as usual he behaved himself in a rough manner; and was sensible that this rough behaviour came not of good, he gathered together a few of his men, and hid himself from Nicanor."}),"\n",(0,h.jsx)(n,{verse:31,children:"But he finding himself notably prevented by the man, came to the great and holy temple: and commanded the priests that were offering the accustomed sacrifices, to deliver him the man."}),"\n",(0,h.jsx)(n,{verse:32,children:"And when they swore unto him, that they knew not where the man was whom he sought, he stretched out his hand to the temple,"}),"\n",(0,h.jsx)(n,{verse:33,children:"And swore, saying: Unless you deliver Judas prisoner to me, I will lay this temple of God even with the ground, and will beat down the altar, and I will dedicate this temple to Bacchus."}),"\n",(0,h.jsx)(n,{verse:34,children:"And when he had spoken thus, he departed. But the priests stretching forth their hands to heaven, called upon him that was ever the defender of their nation, saying in this manner:"}),"\n",(0,h.jsx)(n,{verse:35,children:"Thou, O Lord of all things, who wantest nothing, wast pleased that the temple of thy habitation should be amongst us."}),"\n",(0,h.jsx)(n,{verse:36,children:"Therefore now, O Lord, the holy of all holies, keep this house for ever undefiled, which was lately cleansed."}),"\n",(0,h.jsx)(n,{verse:37,children:"Now Razias, one of the ancients of Jerusalem, was accused to Nicanor, a man that was a lover of the city, and of good report, who for his kindness was called the father of the Jews."}),"\n",(0,h.jsx)(n,{verse:38,children:"This man, for a long time, had held fast his purpose of keeping himself pure in the Jews' religion, and was ready to expose his body and life, that he might persevere therein."}),"\n",(0,h.jsx)(n,{verse:39,children:"So Nicanor being willing to declare the hatred that he bore the Jews, sent five hundred soldiers to take him."}),"\n",(0,h.jsx)(n,{verse:40,children:"For he thought by ensnaring him to hurt the Jews very much."}),"\n",(0,h.jsx)(n,{verse:41,children:"Now as the multitude sought to rush into his house, and to break open the door, and to set fire to it, when he was ready to be taken, he struck himself with his sword:"}),"\n",(0,h.jsx)(t.admonition,{type:"note",children:(0,h.jsx)(t.p,{children:"Note 1: He struck himself, etc...St. Augustine, (Epist. 61, ad Dulcitium, et lib. 2, cap. 23, ad Epist. 2, Gaud.) discussing this fact of Razias, says, that the holy scripture relates it, but doth not praise it, as to be admired or imitated, and that either it was not well done by him, or at least not proper in this time of grace."})}),"\n",(0,h.jsx)(n,{verse:42,children:"Choosing to die nobly rather than to fall into the hands of the wicked, and to suffer abuses unbecoming his noble birth."}),"\n",(0,h.jsx)(n,{verse:43,children:"But whereas through haste he missed of giving a sure wound, and the crowd was breaking into the doors, he ran boldly to the wall, and manfully threw himself down to the crowd:"}),"\n",(0,h.jsx)(n,{verse:44,children:"But they quickly making room for his fall, he came upon the midst of the neck."}),"\n",(0,h.jsx)(t.admonition,{type:"note",children:(0,h.jsx)(t.p,{children:"Note 1: He came upon the midst of the neck...Venit per mediam cervicem. In the Greek it is keneona, which signifies a void place, where there is no building."})}),"\n",(0,h.jsx)(n,{verse:45,children:"And as he had yet breath in him, being inflamed in mind, he arose: and while his blood ran down with a great stream, and he was grievously wounded, he ran through the crowd:"}),"\n",(0,h.jsx)(n,{verse:46,children:"And standing upon a steep rock, when he was now almost without blood, grasping his bowels, with both hands he cast them upon the throng, calling upon the Lord of life and spirit, to restore these to him again: and so he departed this life."})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,h.jsx)(t,{...e,children:(0,h.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>i,x:()=>o});var h=n(14041);const s={},a=h.createContext(s);function i(e){const t=h.useContext(a);return h.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),h.createElement(a.Provider,{value:t},e.children)}}}]);